<?php
if(!defined('ABSPATH'))exit(1);
global$wpdb;$errors=[];$expected=['sources','feed_items','jobs','ai_generations','logs','daily_usage','migration_journal'];
foreach($expected as$logical){$table=$wpdb->prefix.'wpnb_'.$logical;$status=$wpdb->get_row($wpdb->prepare('SHOW TABLE STATUS LIKE %s',$table),ARRAY_A);if(!$status)$errors[]='missing:'.$logical;elseif(strtolower((string)$status['Engine'])!=='innodb')$errors[]='engine:'.$logical.':'.$status['Engine'];}
$plugin=get_plugin_data(WP_PLUGIN_DIR.'/wordpress-news-bot/wordpress-news-bot.php',false,false);if(($plugin['Name']??'')!=='WordPress News Bot')$errors[]='name';if(($plugin['Version']??'')!=='0.4.0-rc.4')$errors[]='version';if(($plugin['AuthorName']??'')!=='Utkuweb')$errors[]='author';if((string)get_option('wpnb_schema_version','')!==WPNB_SCHEMA_VERSION)$errors[]='schema-version';if((string)get_option('wpnb_plugin_version','')!==WPNB_VERSION)$errors[]='plugin-version';$settings=(array)get_option('wpnb_settings',[]);if(($settings['publication_mode']??'')!=='publish')$errors[]='publication-mode';
if($errors){fwrite(STDERR,implode("\n",$errors)."\n");exit(1);}echo json_encode(['tables'=>count($expected),'version'=>$plugin['Version'],'author'=>$plugin['AuthorName']],JSON_UNESCAPED_SLASHES)."\n";
